figure.sourcecode:
commit-receipt = { type: "aiir.commit_receipt", schema: "aiir/commit_receipt.v2", version: semver, commit: commit-object, ai_attestation: ai-attestation, provenance: provenance, receipt_id: receipt-id, content_hash: content-hash, timestamp: date-time, extensions: extensions, }
commit-receipt-core = { type: "aiir.commit_receipt", schema: "aiir/commit_receipt.v2", version: semver, commit: commit-object, ai_attestation: ai-attestation, provenance: provenance, }
commit-object = { sha: git-sha, tree_sha: git-sha / "", parent_shas: [* git-sha], author: git-identity, committer: git-identity, subject: tstr .size (0..4096), message_hash: sha256-prefixed, diff_hash: sha256-prefixed, files_changed: uint, (files-present // files-redacted), ? files_capped: true, }
files-present = (files: [0*100 tstr]) files-redacted = (files_redacted: true)
git-identity = { name: tstr .size (0..1024), email: tstr .size (0..1024), date: tstr, }
ai-attestation = { is_ai_authored: bool, signals_detected: [* tstr], signal_count: uint, detection_method: tstr, ? is_bot_authored: bool, ? bot_signals_detected: [* tstr], ? bot_signal_count: uint, ? authorship_class: authorship-class, }
authorship-class = "human" / "ai_assisted" / "bot" / "ai+bot" / "ai_generated"
provenance = { repository: tstr / null, tool: tool-uri, generator: tstr, }
extensions = { ? instance_id: tstr, ? namespace: tstr, * tstr => any, }
receipt-id = tstr .regexp "^g1-[0-9a-f]{32}$" content-hash = tstr .regexp "^sha256:[0-9a-f]{64}$" semver = tstr git-sha = tstr .regexp "^[0-9a-f]{40}$" / tstr .regexp "^[0-9a-f]{64}$" sha256-prefixed = tstr .regexp "^sha256:[0-9a-f]{64}$" date-time = tstr tool-uri = tstr
